fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // If maxsplit is 0, return the original string as a single-element list
            result.push(vec![s]);
            continue;
        }

        let mut parts = Vec::new();
        let mut remaining = s.as_str();
        let mut splits = 0;

        // Perform the right-split operation
        while splits < maxsplit && remaining.contains(&sep) {
            // Split from the right
            if let Some(pos) = remaining.rfind(&sep) {
                // Push the right part
                parts.push(remaining[pos + sep.len()..].to_string());
                // Update remaining to the left part
                remaining = &remaining[..pos];
                splits += 1;
            }
        }

        // Push the remaining part (or the whole string if no splits were made)
        parts.push(remaining.to_string());

        // Reverse the parts to maintain the right-split order
        parts.reverse();
        result.push(parts);
    }

    result
}